function allIdeas(){return mode==='actual'?actualItems.filter(x=>x.category==='idea').map(x=>[x.name,x.note||'暂无说明',ideaType(x),x.stack||'灵感','',x.updatedAt?.slice(0,10)||'',null,x.id]):[...ideaDefs,...demoDrafts.filter(x=>x.type==='ideas').map(x=>[x.name,x.note,'产品想法','灵感','','刚刚',null])]}
function ideaGrid(){const type=['全部','产品想法','技术方案','行业洞察','生活记录','待整理'][filter];const rows=allIdeas().map((d,i)=>({d,i})).filter(({d})=>(!filter||d[2]===type)&&(!query||d.join(' ').toLowerCase().includes(query.toLowerCase())));return rows.length?rows.map(({d,i})=>`<article class="idea-card" tabindex="0" role="button" data-idea="${i}">${i<12&&mode==='demo'?`<img class="idea-cover" src="${img('idea'+i)}" alt="${esc(d[0])}封面">`:''}<div class="idea-body"><h3>${esc(d[0])}</h3><p>${esc(d[1])}</p><div class="tags">${tag(d[2],d[2]==='生活记录'?'orange':d[2]==='行业洞察'?'green':'purple')}${tag(d[3])}${d[4]?tag(d[4]):''}</div><div class="idea-date"><span>${esc(d[5])}</span><span>•••</span></div></div></article>`).join(''):'<div class="empty-state">没有符合条件的灵感</div>'}
