function liveItems(category){return actualItems.filter(x=>x.category===category).filter(x=>(!query||[x.name,x.url,x.note,x.stack].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!filter||(filter===1?x.status==='active':filter===2?x.status==='planned':x.status==='offline')))}
function liveItemPage(category,title,icon){const all=actualItems.filter(x=>x.category===category);const id=category==='site'?'projectGrid':category==='idea'?'ideaGrid':'toolCategories';return header(title,'来自工作台数据库；状态由已登记记录提供，不代表主动可用性探测。',btn('新增'+(category==='idea'?'灵感':category==='tool'?'工具':'项目'),category==='idea'?'new-idea':category==='tool'?'new-tool':'new-project','primary','plus'),icon)+liveBanner()+`<div class="toolbar">${[ ['全部',all.length],['运行中',all.filter(x=>x.status==='active').length],['规划中',all.filter(x=>x.status==='planned').length],['已下线',all.filter(x=>x.status==='offline').length] ].map(([s,n],i)=>`<button class="pill ${filter===i?'active':''}" data-filter="${i}">${s} (${n})</button>`).join('')}<span class="push"></span>${search('搜索名称、地址、说明…',category==='site'?'projectSearch':category==='idea'?'ideaSearch':'toolSearch')}<div class="seg">${btn('卡片','view-cards',display==='cards'?'active':'','layout-grid')}${btn('列表','view-list',display==='list'?'active':'','list')}</div></div><div id="${id}" class="grid cols3 ${display==='list'?'projects-list':''}">${sourceStatus.items==='error'?unavailable('清单数据','接口读取失败'):liveItems(category).map(liveItemCard).join('')||'<div class="empty-state">暂无符合条件的记录</div>'}</div>`}
function liveRing(){const types=actualStats?.nodes_by_fact_type;if(!types)return unavailable('记忆分类','统计接口不可用');const rows=Object.entries(types),total=rows.reduce((n,[,v])=>n+v,0);let position=0;const colors=['#1d7cff','#00bf90','#9158ff'];const segments=rows.map(([,v],i)=>{const start=position;position+=total?v/total*100:0;return `${colors[i%3]} ${start}% ${position}%`}).join(',');return `<div class="ring-wrap"><div class="ring" style="background:${total?'conic-gradient('+segments+')':'#e8eff8'}"><div class="ring-text"><strong>${number(total)}</strong><small>实际记忆数</small></div></div><div class="ring-legend">${rows.map(([k,v],i)=>`<div><i style="background:${colors[i%3]}"></i>${esc({world:'客观事实',experience:'经历事件',observation:'深度观察'}[k]||k)}<b>${number(v)} (${total?(v/total*100).toFixed(1):'0'}%)</b></div>`).join('')}</div></div>`}
function realBars(){if(sourceStatus.timeseries==='error')return unavailable('记忆增长','时间序列接口读取失败');if(!actualTimeseries.length)return '<div class="empty-state">暂无时间序列</div>';const max=Math.max(1,...actualTimeseries.map(x=>(x.world||0)+(x.experience||0)+(x.observation||0)));return `<div class="real-bars">${actualTimeseries.map(x=>`<div class="real-bar" title="${esc(when(x.time))} · 事实 ${number(x.world)} / 经历 ${number(x.experience)} / 观察 ${number(x.observation)}">${['world','experience','observation'].map((k,i)=>`<i style="height:${(x[k]||0)/max*145}px;background:${['#4980ff','#00be91','#9565ff'][i]}"></i>`).join('')}<small>${esc(new Date(x.time).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric'}))}</small></div>`).join('')}</div><p class="ui-note">近 7 天 · 后端 created_at 入库时间 · 蓝：事实 / 绿：经历 / 紫：观察</p>`}
function realGraph(){if(!actualGraph?.nodes?.length)return unavailable('知识图谱',sourceStatus.graph==='error'?'图谱接口读取失败':'暂无图谱节点');const nodes=actualGraph.nodes.slice(0,18),pos=new Map(nodes.map((x,i)=>[x.data.id,{x:170+125*Math.cos(i*2*Math.PI/nodes.length),y:100+70*Math.sin(i*2*Math.PI/nodes.length)}]));return `<svg class="real-graph" viewBox="0 0 340 200" aria-label="实际记忆图谱取样">${(actualGraph.edges||[]).filter(e=>pos.has(e.data.source)&&pos.has(e.data.target)).map(e=>{const a=pos.get(e.data.source),b=pos.get(e.data.target);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#cbdcf8"/>`}).join('')}${nodes.map(n=>{const p=pos.get(n.data.id);return `<g><title>${esc(n.data.label||n.data.text||n.data.id)}</title><circle cx="${p.x}" cy="${p.y}" r="7" fill="#3e76ff"/><text x="${p.x}" y="${p.y+19}" text-anchor="middle" font-size="8" fill="#667da8">${esc((n.data.label||n.data.text||'记忆').slice(0,8))}</text></g>`}).join('')}</svg><p class="ui-note">显示 ${nodes.length} 个节点；图谱接口总量 ${number(actualGraph.total_units)}，并非全库展示。</p>`}
function liveMemoryRows(){let previous='';return actualMemories.map((m,i)=>{const date=m.mentioned_at||m.date||m.updated_at;const parsed=date?new Date(date):null;const group=parsed&&!Number.isNaN(parsed.getTime())?parsed.toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}):'时间未知';const heading=group!==previous?`<h3 class="day">${esc(group)}</h3>`:'';previous=group;return `${heading}<article class="timeline-row ${selectedMemory===i?'active':''}" role="button" tabindex="0" data-memory="${i}"><span class="timeline-time">${parsed&&!Number.isNaN(parsed.getTime())?esc(parsed.toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})):'—'}</span>${tile('file-text',m.fact_type==='observation'?'purple':'')}<div class="timeline-copy"><h4>${esc((m.text||'无正文').slice(0,45))}</h4><p>${esc(m.text||'')}</p>${tags((m.tags||[]).slice(0,4))}</div><span class="tiny-label">${esc({world:'事实',experience:'经历',observation:'观察'}[m.fact_type]||m.fact_type||'记忆')}</span></article>`}).join('')||'<div class="empty-state">暂无记忆条目</div>'}
function metricHistory(){const rows=actualSystem?.history||[];if(rows.length<2)return '<div class="empty-state">正在累积真实采样，至少需要两个采样点；不补造历史曲线。</div>';return `<svg class="monitor-chart" viewBox="0 0 400 180" preserveAspectRatio="none" aria-label="实际服务器采样曲线">${[0,25,50,75,100].map(v=>`<path d="M30 ${150-v*1.35}H398" stroke="#e6eefb" stroke-dasharray="2 2"/><text x="0" y="${154-v*1.35}" fill="#8c9abc" font-size="10">${v}%</text>`).join('')}${['cpu','memory','disk'].map((k,j)=>`<polyline points="${rows.map((r,i)=>r[k]==null?'':`${30+i*367/Math.max(1,rows.length-1)},${150-r[k]*1.35}`).filter(Boolean).join(' ')}" fill="none" stroke="${['#4d80ff','#ffad48','#00be9b'][j]}" stroke-width="1.4"/>`).join('')}${Array.from({length:6},(_,i)=>{const row=rows[Math.round(i*(rows.length-1)/5)];return `<text x="${30+i*65}" y="175" fill="#8190b2" font-size="10">${esc(shortTime(row.time).slice(0,5))}</text>`}).join('')}</svg><p class="ui-note">蓝：CPU / 橙：内存 / 绿：磁盘 · ${esc(when(rows[0].time))} 至 ${esc(when(rows.at(-1).time))}</p>`}

function liveActivity(){return actualActivity.length?table(['时间','操作','资源','状态'],actualActivity.slice(0,12).map(a=>[esc(when(a.time)),esc(a.method),esc(a.resource),number(a.status)])):'<div class="empty-state">本次接入后尚无工作台写操作记录；不回填虚构日志。</div>'}
function liveOverviewPage(){return header('总览','工作台与 Hindsight 的实际数据快照。',linkbtn('原生控制台','/console','primary','terminal'),'home')+liveBanner()+`<div class="kpis">${liveMetric(sourceStatus.items==='ok'?number(actualItems.length):'—','项目/工具/资产记录','folder')}${liveMetric(number(actualStats?.total_nodes),'记忆条目','brain','purple')}${liveMetric(number(actualStats?.total_documents),'归档文档','file-text')}${liveMetric(actualContainers?.ok?number(actualContainers.running):'—','运行中容器','container','green')}</div><div class="grid live-overview-grid">${panel('记忆增长 · 实际入库',realBars())}${panel('事实构成',liveRing())}</div>${panel('我的项目',`<div class="grid cols3">${actualItems.filter(x=>x.category==='site').map(liveItemCard).join('')||'<div class="empty-state">暂无项目记录</div>'}`,actionLink('查看全部','go-projects'))}`}
// Actual data occupies the reference components; missing integrations retain their slots.
const shortDate=value=>value?new Date(value).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}):'—';
const shortTime=value=>value?new Date(value).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'等待连接';
function liveBanner(){return `<div class="live-status" role="status" title="${esc('每30秒刷新；最近完成 '+when(lastRefresh)+'；后台采样 '+when(actualSystem?.collectedAt))}"><span class="${dataError?'live-warning':''}">${dataError?'部分接口异常':lastRefresh?'已更新 '+esc(shortTime(lastRefresh)):'正在连接…'}</span>${btn('','live-refresh','small','refresh')}${btn('接口状态','live-sources','small')}</div>${dataError?`<button class="live-error" data-action="live-sources">${esc(dataError)}接口不可用 · 查看详情</button>`:''}`}
function placeholderRows(labels,icon='file-text'){return labels.map(label=>`<div class="pending-row">${tile(icon)}<div><strong>${esc(label)}</strong><small>待接入</small></div><span class="pending-chip">待接入</span></div>`).join('')}
function itemArtwork(x){const rules=[[/hindsight|记忆/i,'hindsight','brain','purple'],[/blog|博客/i,'blog','file-text','purple'],[/shop|商店|商城/i,'shop','cart',''],[/aihot|采集/i,'aihot','database','orange'],[/sunlife|生活助手/i,'sunlife','swirl','green'],[/x-ui|节点/i,'xui','layout-grid',''],[/文件|voidsignal/i,'upload','code',''],[/主站|官网/i,'main','home','orange'],[/工作台|workspace/i,'workspace','globe','green']];const r=rules.find(([re])=>re.test(x.name+' '+x.url));return r?{shot:r[1],icon:r[2],color:r[3]}:{shot:'workspace',icon:'globe',color:''}}
function liveItemCard(x){if(!x)return '';const art=itemArtwork(x),label={active:'运行中',planned:'规划中',internal:'内网',offline:'已下线'}[x.status]||'状态未知';const color=x.status==='planned'?'planned':['internal','offline'].includes(x.status)?'gray':'';let domain='';try{domain=x.url?new URL(x.url,location.origin).host:''}catch{}
 return `<article class="project-card live-item" data-record-id="${esc(x.id)}" data-updated="${esc(x.updatedAt||'')}"><button class="cardmore" data-action="live-detail" aria-label="${esc(x.name)}更多">•••</button><div class="project-top"><img class="tile" src="${img('picon'+Math.max(0,['workspace','blog','main','shop','hindsight','aihot','sunlife','upload','xui'].indexOf(art.shot)))}" alt=""><div class="project-name"><h3>${esc(x.name)}</h3>${badge(label,color)}<div class="project-domain">${esc(domain||'地址待配置')}</div></div></div><div class="project-copy"><p>${esc(x.note||'暂无项目说明')}</p>${tags((x.stack||'项目').split(/[,，、|]/).filter(Boolean).slice(0,3),art.color==='purple'?'purple':'')}</div><img class="project-shot" src="${img(art.shot)}" alt="界面装饰示意" title="装饰示意图，不代表当前运行画面"><div class="project-meta"><span title="文档统计待接入">${ico('file-text')}—</span><span title="成员统计待接入">${ico('people')}—</span><span title="访问统计待接入">${ico('eye')}—</span><span title="${esc(when(x.updatedAt))}">${ico('calendar')}${esc(shortDate(x.updatedAt))}</span></div><div class="project-actions">${x.url?linkbtn('打开',x.url,'blue'):btn('查看','live-detail','blue')}${x.adminUrl?linkbtn('管理台',x.adminUrl):btn('详情','live-detail')}${btn('编辑','live-edit','','pencil')}${btn('•••','live-detail','more')}</div></article>`}
function liveProjectPage(){const all=actualItems.filter(x=>x.category==='site');return header('我的项目','管理所有对外业务与内部项目，支持快速访问、部署状态监控与协作管理。',btn('新建项目　⌄','new-project','primary','plus'))+liveBanner()+`<div class="toolbar"><button class="pill ${!filter?'active':''}" data-filter="0">全部 (${all.length})</button><button class="pill ${filter===1?'active':''}" data-filter="1"><i></i>运行中 (${all.filter(x=>x.status==='active').length})</button><button class="pill purple ${filter===2?'active':''}" data-filter="2"><i></i>规划中 (${all.filter(x=>x.status==='planned').length})</button><button class="pill ${filter===3?'active':''}" data-filter="3">♧ 已归档 (${all.filter(x=>x.status==='offline').length})</button><span class="push"></span><div class="seg">${btn('卡片视图','view-cards',display==='cards'?'active':'','layout-grid')}${btn('列表视图','view-list',display==='list'?'active':'','list')}</div>${select(['↕ 最新更新','名称排序','最早创建'],'projectSort')}${btn('筛选','project-filter','','filter')}</div><div id="projectGrid" class="grid cols3 ${display==='list'?'projects-list':''}">${sourceStatus.items==='error'?unavailable('清单数据','接口读取失败'):liveItems('site').map(liveItemCard).join('')||'<div class="empty-state">暂无符合条件的记录</div>'}</div>`}
function ideaType(x){return ['产品想法','技术方案','行业洞察','生活记录'].find(t=>(x.stack||'').includes(t))||'待整理'}
function liveIdeaCards(){const rows=actualItems.filter(x=>x.category==='idea');const type=['全部','产品想法','技术方案','行业洞察','生活记录','待整理'][filter];return rows.map((x,i)=>({x,i})).filter(({x})=>(!filter||ideaType(x)===type)&&(!query||[x.name,x.note,x.stack].join(' ').toLowerCase().includes(query.toLowerCase()))).map(({x,i})=>`<article class="idea-card" role="button" tabindex="0" data-idea="${i}"><img class="idea-cover" src="${img('idea'+i%12)}" alt="装饰封面"><div class="idea-body"><h3>${esc(x.name)}</h3><p>${esc(x.note||'暂无描述')}</p>${tags([ideaType(x),...(x.stack||'').split(/[,，、|]/).filter(t=>t&&t!==ideaType(x)).slice(0,2)])}<div class="idea-date"><span>${esc(shortDate(x.updatedAt))} ${esc(shortTime(x.updatedAt))}</span><span>•••</span></div></div></article>`).join('')||'<div class="empty-state">暂无符合条件的灵感</div>'}
function liveIdeasPage(){const all=actualItems.filter(x=>x.category==='idea'),types=['全部','产品想法','技术方案','行业洞察','生活记录','待整理'];const tagCounts=new Map();all.forEach(x=>(x.stack||'').split(/[,，、|]/).filter(Boolean).forEach(t=>tagCounts.set(t,(tagCounts.get(t)||0)+1)));return header('灵感','把一闪而过的想法记录下来，让灵感不再流失。',btn('新增灵感　⌄','new-idea','primary','plus'),'bulb')+liveBanner()+`<div class="split"><div><div class="toolbar" style="margin:0"><div style="flex:1;min-width:0">${tabs(types.map(t=>t+' ('+(t==='全部'?all.length:all.filter(x=>ideaType(x)===t).length)+')'),'idea-filter',filter)}</div><div class="seg">${btn('卡片视图','view-cards',display==='cards'?'active':'','layout-grid')}${btn('列表视图','view-list',display==='list'?'active':'','list')}${btn('看板视图','view-board',display==='board'?'active':'','layout-grid')}</div></div><div class="toolbar">${search('搜索灵感内容…','ideaSearch')}${select(['全部标签',...tagCounts.keys()],'ideaTag')}${select(['全部类型',...types.slice(1)],'ideaType')}${select(['最新创建','最早创建'],'ideaSort')}</div><div class="ideas-grid ${display==='list'?'list-mode':display==='board'?'board-mode':''}" id="ideaGrid">${sourceStatus.items==='error'?unavailable('灵感清单','接口读取失败'):liveIdeaCards()}</div></div><aside class="stack">${panel('灵感统计',`<div class="mini-stats">${[['总灵感数',all.length,'bulb','orange'],['产品想法',all.filter(x=>ideaType(x)==='产品想法').length,'file-text','purple'],['技术方案',all.filter(x=>ideaType(x)==='技术方案').length,'terminal',''],['行业洞察',all.filter(x=>ideaType(x)==='行业洞察').length,'trending','orange']].map(s=>`<div class="mini-stat">${tile(s[2],s[3])}<div><strong>${sourceStatus.items==='ok'?s[1]:'—'}</strong><p>${s[0]}</p><small class="neutral">已保存记录</small></div></div>`).join('')}</div>`,select(['全部']))}${panel('热门标签',tagCounts.size?tagcloud([...tagCounts.entries()].sort((a,b)=>b[1]-a[1]).slice(0,16)):'<div class="empty-state">暂无已登记标签</div>',actionLink('全部标签','tags'))}${panel('快速记录灵感',`<textarea class="quick-note" id="quickNote" placeholder="记录你的灵感…"></textarea><div class="quick-footer">${ico('image')}${ico('link')}${ico('file-text')} #<span class="push"></span>${select(['私有'])}${btn('保存','quick-save','primary small')}</div>`,btn('◉ AI 辅助','pending','small'))}${panel('灵感收集箱','<p class="ui-note">从其他平台快速收集灵感 · 待接入</p><div class="collection-buttons">'+['网页剪藏','截图识别','API 收集','稍后阅读'].map(t=>btn(t,'pending','small','file-text')).join('')+'</div>')}</aside></div>`}
function liveMemoryPage(){return header('记忆系统','把 Hindsight 挂载到你的 AI 客户端，让它自动读写长期记忆。',btn('使用指南','guide','','book')+btn('设置','memory-settings','','settings')+btn('新增记忆 ⌄','new-memory','primary','plus'))+liveBanner()+`<div class="kpis">${liveMetric(number(actualStats?.total_nodes),'总记忆条数','file-text','purple')}${liveMetric(number(actualStats?.total_links),'关联链接','link','green')}${liveMetric(number(actualStats?.total_documents),'归档文档','file-text')}${liveMetric(number(actualStats?.nodes_by_fact_type?.observation),'深度观察','eye')}</div><div class="memory-layout ${!detailOpen?'full-detail-hidden':''}"><aside class="stack">${panel('记忆分类',liveRing())}${panel('标签云',sourceStatus.tags==='error'?unavailable('标签','接口读取失败'):tagcloud(actualTags.slice(0,16).map(x=>[x.tag,number(x.count)]))||'<div class="empty-state">暂无标签</div>',actionLink('全部标签 ('+actualTags.length+')','tags'))}${panel('知识图谱',realGraph(),actionLink('查看完整图谱','graph'))}</aside><section class="panel memory-stream"><div class="tabs" data-tabgroup="live-memory-filter">${[['全部记忆',actualStats?.total_nodes,''],['客观事实',actualStats?.nodes_by_fact_type?.world,'world'],['经历事件',actualStats?.nodes_by_fact_type?.experience,'experience'],['深度观察',actualStats?.nodes_by_fact_type?.observation,'observation']].map(([s,n,k])=>`<button class="tab ${memFilter===k?'active':''}" data-memory-type="${k}">${s} (${number(n)})</button>`).join('')}</div><div class="toolbar">${search('在后端搜索全部记忆…','memorySearch')}${select(['全部类型','world','experience','observation'],'liveMemoryType')}${btn('标签','tags','small')}${btn('时间','memory-source-info','small')}</div><p class="ui-note memory-load-status">已加载 ${actualMemories.length} / ${number(memoryTotal)} 条 · 搜索由后端执行</p>${memoryTag?`<div class="toolbar">${tag(memoryTag)}${btn('清除标签筛选','live-clear-memory','small')}</div>`:''}<div id="memoryRows">${sourceStatus.memories==='error'?unavailable('记忆列表','接口读取失败'):liveMemoryRows()}</div>${actualMemories.length<(memoryTotal||0)?btn('加载更多','live-more','blue'):''}</section>${detailOpen?`<aside class="panel memory-detail" id="memoryDetail">${liveMemoryDetail()}</aside>`:''}</div>`}
function liveMemoryDetail(){const m=actualMemories[selectedMemory];if(!m)return '<div class="empty-state">选择一条记忆查看详情</div>';return `<div class="detail-cover"><img class="detail-image" src="${img('memory-cover')}" alt="装饰封面"><button class="btn small" data-action="close-detail" aria-label="关闭详情">×</button></div><div class="detail-body"><h3>${esc((m.text||'记忆条目').slice(0,40))}</h3><div class="detail-meta">${ico('clock')}${esc(when(m.mentioned_at||m.date))}　${esc(m.fact_type||'记忆')}</div><h4>内容摘要</h4><p class="live-memory-text">${esc(m.text||'暂无正文')}</p><h4>标签</h4>${tags(m.tags||[])}<h4>来源上下文</h4><p>${esc(m.context||'暂无上下文')}</p><h4>原始来源</h4><div class="detail-link">${ico('file-text')}<span>${esc(m.document_id||m.id)}</span></div><p class="ui-note">事件：${esc(when(m.mentioned_at||m.date))}<br>更新：${esc(when(m.updated_at))}</p></div><div class="detail-footer">${btn('编辑','edit-memory','','pencil')}${btn('复制内容','copy-memory','','copy')}${btn('删除','delete-memory','danger','trash')}</div>`}
function liveContainerTable(status=''){const c=actualContainers;if(!c?.ok)return unavailable('容器监控','接口读取失败');return table(['名称','状态','镜像','CPU','内存','操作'],c.containers.filter(x=>!status||(status==='运行中'?x.status==='running':status==='已停止'?['exited','created'].includes(x.status):!['running','exited','created'].includes(x.status))).map(x=>[esc(x.name),badge(x.status==='running'?'运行中':x.status==='exited'?'已停止':esc(x.status),x.status==='running'?'':'gray'),esc(x.image),percent(x.cpuPercent),esc(x.memory?.split(' / ')[0]||'—'),rowMore()]))}
