function formFields(kind,record={}){if(kind==='creds')return `<label for="editName">名称 *</label><input id="editName" required maxlength="80" value="${esc(record.name||'')}"><label for="editKind">类型</label><select id="editKind">${['api','ssh','cloudflare','github','db','other'].map(x=>`<option ${record.kind===x?'selected':''}>${x}</option>`).join('')}</select><label for="editScope">适用范围</label><input id="editScope" value="${esc(record.scope||'')}"><label for="editUser">账号</label><input id="editUser" autocomplete="off" value="${esc(record.username||'')}"><label for="editSecret">Token / API Key（留空保留已有值）</label><input id="editSecret" type="password" autocomplete="new-password"><label for="editPassword">密码（留空保留已有值）</label><input id="editPassword" type="password" autocomplete="new-password"><label for="editNote">备注</label><textarea id="editNote" rows="3">${esc(record.note||'')}</textarea>`;return `<label for="editName">名称 *</label><input id="editName" required maxlength="80" value="${esc(record.name||'')}"><label for="editUrl">访问地址</label><input id="editUrl" type="url" placeholder="https://…" value="${esc(record.url||'')}"><label for="editAdmin">管理台</label><input id="editAdmin" value="${esc(record.adminUrl||'')}"><label for="editRepo">代码仓库</label><input id="editRepo" value="${esc(record.repoUrl||'')}"><label for="editPath">部署路径</label><input id="editPath" value="${esc(record.deployPath||'')}"><label for="editStack">技术栈 / 标签</label><input id="editStack" value="${esc(record.stack||'')}"><label for="editStatus">状态</label><select id="editStatus">${[['active','运行中'],['planned','规划中'],['internal','内网'],['offline','已下线']].map(([v,t])=>`<option value="${v}" ${record.status===v?'selected':''}>${t}</option>`).join('')}</select><label for="editNote">描述</label><textarea id="editNote" rows="3">${esc(record.note||'')}</textarea>`}
