async function saveEditor(){if(saving||!editing)return;const name=$('#editName').value.trim();if(!name){$('#formError').textContent='请填写名称';$('#editName').focus();return}const note=$('#editNote').value;const kind=editing.kind;const payload={name,note};if(kind==='creds'){payload.kind=$('#editKind').value;payload.scope=$('#editScope').value;payload.username=$('#editUser').value;if($('#editSecret').value)payload.token=$('#editSecret').value;if($('#editPassword').value)payload.password=$('#editPassword').value}else{Object.assign(payload,{category:{projects:'site',ideas:'idea',tools:'tool',infra:'infra'}[kind]||'site',url:$('#editUrl').value,adminUrl:$('#editAdmin').value,repoUrl:$('#editRepo').value,deployPath:$('#editPath').value,stack:$('#editStack').value,status:$('#editStatus').value})}if(mode==='demo'){if(kind==='creds'){closeDialog();toast('凭据界面演示完成；未保存任何密码或密钥');return}if(editing.demoIndex!==undefined){const idx=editing.demoIndex;if(kind==='projects'&&idx<projects.length){projects[idx][0]=name;projects[idx][2]=note;projects[idx][12]=payload.url}else if(kind==='ideas'&&idx<ideaDefs.length){ideaDefs[idx][0]=name;ideaDefs[idx][1]=note}else demoDrafts.push({type:kind,name,note})}else demoDrafts.push({type:kind,name,note});closeDialog();render();toast('已保存本次界面演示草稿');return}const endpoint=kind==='creds'?'creds':'items';saving=true;try{await api('/api/wb/'+endpoint+(editing.id?'/'+encodeURIComponent(editing.id):''),{method:editing.id?'PATCH':'POST',body:JSON.stringify(payload)});closeDialog();await loadActual();toast('已保存')}catch(e){if($('#formError'))$('#formError').textContent=e.message}finally{saving=false}}
